edits.before:
name: workspace-mcp
stages:
  pending: {initial: true}
  working: {}
  complete: {terminal: true}
pins:
  inputs:
    - work.requested

edits.after:
name: workspace-mcp
stages:
  pending: {}
  working: {}
  complete: {final: true}
pins:
  inputs:
    - work.requested

edits.before:
name: clock-public-boundary
stages:
  pending: {initial: true}
  done: {terminal: true}
schedules:
  poll: {every: 250ms, emit: poll.tick}
pins:
  inputs: [start.requested]
  outputs: [poll.tick]

edits.after:
name: clock-public-boundary
stages:
  pending: {}
  done: {final: true}
schedules:
  poll: {every: 250ms, emit: poll.tick}
pins:
  inputs: [start.requested]
  outputs: [poll.tick]
